<script>
// Funcionalidad del modal de Instagram
document.addEventListener('DOMContentLoaded', function() {
    const modal = document.getElementById('instagramModal');
    const modalImage = document.getElementById('modalImage');
    const modalDescription = document.getElementById('modalDescription');
    const modalLikes = document.getElementById('modalLikes');
    const modalTime = document.getElementById('modalTime');
    const closeBtn = document.querySelector('.instagram-modal-close');
    const clickablePosts = document.querySelectorAll('.instagram-post-clickable');

    // Abrir modal cuando se hace clic en una imagen
    clickablePosts.forEach(post => {
        post.addEventListener('click', function(e) {
            e.preventDefault();
            
            const image = this.dataset.image;
            const text = this.dataset.text;
            const likes = this.dataset.likes;
            const url = this.dataset.url;
            
            // Establecer contenido del modal
            modalImage.src = image;
            modalDescription.textContent = text;
            modalLikes.textContent = `${likes} ${likes == 1 ? 'like' : 'likes'}`;
            modalTime.textContent = 'MAY 12';
            
            // Mostrar modal con animación
            modal.style.display = 'block';
            document.body.style.overflow = 'hidden';
            
            // Funcionalidad para ir a Instagram
            modal.setAttribute('data-instagram-url', url);
        });
    });

    // Cerrar modal
    function closeModal() {
        modal.style.display = 'none';
        document.body.style.overflow = 'auto';
    }

    // Cerrar al hacer clic en X
    closeBtn.addEventListener('click', closeModal);

    // Cerrar al hacer clic fuera del modal
    modal.addEventListener('click', function(e) {
        if (e.target === modal) {
            closeModal();
        }
    });

    // Cerrar con tecla Escape
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && modal.style.display === 'block') {
            closeModal();
        }
    });

    // Funcionalidad de botones del modal
    const likeBtn = document.querySelector('.like-btn');
    const followBtn = document.querySelector('.modal-follow-btn');
    const shareBtn = document.querySelector('.share-btn');
    const saveBtn = document.querySelector('.save-btn');

    // Botón de like
    likeBtn.addEventListener('click', function() {
        this.classList.toggle('liked');
        const likesElement = document.getElementById('modalLikes');
        const currentLikes = parseInt(likesElement.textContent);
        
        if (this.classList.contains('liked')) {
            likesElement.textContent = `${currentLikes + 1} likes`;
        } else {
            likesElement.textContent = `${currentLikes - 1} likes`;
        }
    });

    // Botón de follow
    followBtn.addEventListener('click', function() {
        if (this.textContent === 'Follow') {
            this.textContent = 'Following';
            this.style.background = '#efefef';
            this.style.color = '#262626';
        } else {
            this.textContent = 'Follow';
            this.style.background = '#0095f6';
            this.style.color = 'white';
        }
    });

    // Botón de share
    shareBtn.addEventListener('click', function() {
        const instagramUrl = modal.getAttribute('data-instagram-url');
        if (navigator.share) {
            navigator.share({
                title: 'Latino Knowledge Instagram Post',
                url: instagramUrl
            });
        } else {
            // Fallback: copiar al portapapeles
            navigator.clipboard.writeText(instagramUrl).then(() => {
                alert('¡Link copiado al portapapeles!');
            });
        }
    });

    // Input de comentario
    const commentInput = document.querySelector('.modal-comment-input input');
    const postBtn = document.querySelector('.modal-post-btn');

    commentInput.addEventListener('input', function() {
        if (this.value.trim()) {
            postBtn.style.opacity = '1';
            postBtn.style.pointerEvents = 'auto';
        } else {
            postBtn.style.opacity = '0.3';
            postBtn.style.pointerEvents = 'none';
        }
    });

    postBtn.addEventListener('click', function() {
        if (commentInput.value.trim()) {
            alert('¡Comentario enviado! (Esta es una demo)');
            commentInput.value = '';
            this.style.opacity = '0.3';
            this.style.pointerEvents = 'none';
        }
    });

    // Estilo inicial del botón post
    postBtn.style.opacity = '0.3';
    postBtn.style.pointerEvents = 'none';
});
</script>
